  _spawn_res.stdin_parent_fd = -1;
  _spawn_res.stdout_parent_fd = -1;
  _spawn_res.stderr_parent_fd = -1;

  int stdin_pipe[2] = {-1, -1};
  int stdout_pipe[2] = {-1, -1};
  int stderr_pipe[2] = {-1, -1};

